137	/**
138	 * Composite tool invocation that types a full string by calling press_key
139	 * for each character internally, avoiding N model round-trips.
140	 */
141	class TypeTextInvocation extends BaseToolInvocation<
142	  Record<string, unknown>,
143	  ToolResult
144	> {
145	  constructor(
146	    private readonly browserManager: BrowserManager,
147	    private readonly text: string,
148	    private readonly submitKey: string | undefined,
149	    messageBus: MessageBus,
150	  ) {
151	    super({ text, submitKey }, messageBus, 'type_text', 'type_text');
152	  }
153	
154	  getDescription(): string {
155	    const preview = `"${this.text.substring(0, 50)}${this.text.length > 50 ? '...' : ''}"`;
156	    return this.submitKey
157	      ? `type_text: ${preview} + ${this.submitKey}`
158	      : `type_text: ${preview}`;
159	  }
160	
161	  protected override async getConfirmationDetails(
162	    _abortSignal: AbortSignal,
163	  ): Promise<ToolCallConfirmationDetails | false> {
164	    if (!this.messageBus) {
165	      return false;
166	    }
167	
168	    return {
169	      type: 'mcp',
170	      title: `Confirm Tool: type_text`,
171	      serverName: 'browser-agent',
172	      toolName: 'type_text',
173	      toolDisplayName: 'type_text',
174	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
175	        await this.publishPolicyUpdate(outcome);
176	      },
177	    };
178	  }
179	
180	  override getPolicyUpdateOptions(
181	    _outcome: ToolConfirmationOutcome,
182	  ): PolicyUpdateOptions | undefined {
183	    return {
184	      mcpName: 'browser-agent',
185	    };
186	  }
187	
188	  override async execute(signal: AbortSignal): Promise<ToolResult> {
189	    try {
