191	        return {
192	          llmContent: 'Error: Operation cancelled before typing started.',
193	          returnDisplay: 'Operation cancelled before typing started.',
194	          error: { message: 'Operation cancelled' },
195	        };
196	      }
197	
198	      await this.typeCharByChar(signal);
199	
200	      // Optionally press a submit key (Enter, Tab, etc.) after typing
201	      if (this.submitKey && !signal.aborted) {
202	        const keyResult = await this.browserManager.callTool(
203	          'press_key',
204	          { key: this.submitKey },
205	          signal,
206	        );
207	        if (keyResult.isError) {
208	          const errText = this.extractErrorText(keyResult);
209	          debugLogger.warn(
210	            `type_text: submitKey("${this.submitKey}") failed: ${errText}`,
211	          );
212	        }
213	      }
214	
215	      const summary = this.submitKey
216	        ? `Successfully typed "${this.text}" and pressed ${this.submitKey}`
217	        : `Successfully typed "${this.text}"`;
218	
219	      return {
220	        llmContent: summary,
221	        returnDisplay: summary,
222	      };
223	    } catch (error) {
224	      const errorMsg = error instanceof Error ? error.message : String(error);
225	
226	      // Chrome connection errors are fatal
227	      if (errorMsg.includes('Could not connect to Chrome')) {
228	        throw error;
229	      }
230	
231	      debugLogger.error(`type_text failed: ${errorMsg}`);
232	      return {
233	        llmContent: `Error: ${errorMsg}`,
234	        returnDisplay: `Error: ${errorMsg}`,
235	        error: { message: errorMsg },
236	      };
237	    }
238	  }
