130	  /**
131	   * Calls a tool on the MCP server.
132	   *
133	   * @param toolName The name of the tool to call
134	   * @param args Arguments to pass to the tool
135	   * @param signal Optional AbortSignal to cancel the call
136	   * @returns The result from the MCP server
137	   */
138	  async callTool(
139	    toolName: string,
140	    args: Record<string, unknown>,
