/**
 * @fileoverview Input-blocking overlay utilities for browser automation.
 *
 * Provides functions to inject and remove a full-page overlay that intercepts
 * user input (clicks, keyboard focus, scrolling via pointer) while the browser
 * is being driven by the AI agent. This prevents a human from interfering with
 * an in-flight automated operation.
 *
 * Unlike the purely-visual automation overlay (which never captures pointer
 * events), this blocker sets `pointer-events: auto` so it swallows real user
 * interaction. Because the blocker would also swallow the agent's own synthetic
 * interactions, it must be suspended around each interactive tool call and
 * resumed afterwards — see `buildSuspendScript` / `buildResumeScript`.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input blocker.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 *
 * Avoids nested template literals by using string concatenation for styles.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483646',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'center',
      background: 'transparent',
    });

    const banner = document.createElement('div');
    banner.textContent = 'Gemini CLI is controlling this browser';
    Object.assign(banner.style, {
      marginTop: '12px',
      padding: '6px 14px',
      borderRadius: '6px',
      background: 'rgba(66,133,244,0.95)',
      color: '#fff',
      font: '13px system-ui, sans-serif',
      pointerEvents: 'none',
    });
    blocker.appendChild(banner);

    document.documentElement.appendChild(blocker);

    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input blocker.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the JavaScript function string that suspends the input blocker so an
 * automated interaction can reach the underlying page, then can be resumed.
 */
export function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that re-enables the input blocker after
 * an automated interaction has completed.
 */
export function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Errors from the underlying evaluate_script call are swallowed and the promise
 * resolves with `undefined` so blocker failures never interrupt automation.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Errors from the underlying evaluate_script call are swallowed and the promise
 * resolves with `undefined` so blocker failures never interrupt automation.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}
