7	/**
8	 * @fileoverview Factory for creating browser agent definitions with configured tools.
9	 *
10	 * This factory is called when the browser agent is invoked via delegate_to_agent.
11	 * It creates a BrowserManager, connects the isolated MCP client, wraps tools,
12	 * and returns a fully configured LocalAgentDefinition.
13	 *
14	 * IMPORTANT: The MCP tools are ONLY available to the browser agent's isolated
15	 * registry. They are NOT registered in the main agent's ToolRegistry.
16	 */
17	
18	import type { Config } from '../../config/config.js';
19	import { AuthType } from '../../core/contentGenerator.js';
20	import type { LocalAgentDefinition } from '../types.js';
21	import type { MessageBus } from '../../confirmation-bus/message-bus.js';
22	import type { AnyDeclarativeTool } from '../../tools/tools.js';
23	import { BrowserManager } from './browserManager.js';
24	import {
25	  BrowserAgentDefinition,
26	  type BrowserTaskResultSchema,
27	} from './browserAgentDefinition.js';
28	import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
29	import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';
30	import { injectAutomationOverlay } from './automationOverlay.js';
31	import { debugLogger } from '../../utils/debugLogger.js';
32	
33	/**
34	 * Creates a browser agent definition with MCP tools configured.
35	 *
36	 * This is called when the browser agent is invoked via delegate_to_agent.
37	 * The MCP client is created fresh and tools are wrapped for the agent's
38	 * isolated registry - NOT registered with the main agent.
39	 *
40	 * @param config Runtime configuration
41	 * @param messageBus Message bus for tool invocations
42	 * @param printOutput Optional callback for progress messages
43	 * @returns Fully configured LocalAgentDefinition with MCP tools
44	 */
45	export async function createBrowserAgentDefinition(
46	  config: Config,
47	  messageBus: MessageBus,
48	  printOutput?: (msg: string) => void,
49	): Promise<{
50	  definition: LocalAgentDefinition<typeof BrowserTaskResultSchema>;
51	  browserManager: BrowserManager;
52	}> {
53	  debugLogger.log(
54	    'Creating browser agent definition with isolated MCP tools...',
55	  );
56	
57	  // Create and initialize browser manager with isolated MCP client
58	  const browserManager = new BrowserManager(config);
59	  await browserManager.ensureConnection();
60	
61	  if (printOutput) {
62	    printOutput('Browser connected with isolated MCP client.');
63	  }
64	
65	  // Inject automation overlay if not in headless mode
66	  const browserConfig = config.getBrowserAgentConfig();
67	  if (!browserConfig?.customConfig?.headless) {
68	    if (printOutput) {
69	      printOutput('Injecting automation overlay...');
70	    }
71	    await injectAutomationOverlay(browserManager);
72	  }
73	
74	  // Create declarative tools from dynamically discovered MCP tools
75	  // These tools dispatch to browserManager's isolated client
76	  const mcpTools = await createMcpDeclarativeTools(browserManager, messageBus);
77	  const availableToolNames = mcpTools.map((t) => t.name);
78	
79	  // Validate required semantic tools are available
80	  const requiredSemanticTools = [
81	    'click',
82	    'fill',
83	    'navigate_page',
84	    'take_snapshot',
85	  ];
86	  const missingSemanticTools = requiredSemanticTools.filter(
87	    (t) => !availableToolNames.includes(t),
88	  );
89	  if (missingSemanticTools.length > 0) {
90	    debugLogger.warn(
91	      `Semantic tools missing (${missingSemanticTools.join(', ')}). ` +
92	        'Some browser interactions may not work correctly.',
93	    );
94	  }
95	
96	  // Only click_at is strictly required — text input can use press_key or fill.
97	  const requiredVisualTools = ['click_at'];
98	  const missingVisualTools = requiredVisualTools.filter(
99	    (t) => !availableToolNames.includes(t),
100	  );
101	
102	  // Check whether vision can be enabled; returns undefined if all gates pass.
103	  function getVisionDisabledReason(): string | undefined {
104	    const browserConfig = config.getBrowserAgentConfig();
105	    if (!browserConfig.customConfig.visualModel) {
106	      return 'No visualModel configured.';
107	    }
108	    if (missingVisualTools.length > 0) {
109	      return (
110	        `Visual tools missing (${missingVisualTools.join(', ')}). ` +
111	        `The installed chrome-devtools-mcp version may be too old.`
112	      );
113	    }
114	    const authType = config.getContentGeneratorConfig()?.authType;
115	    const blockedAuthTypes = new Set([
116	      AuthType.LOGIN_WITH_GOOGLE,
117	      AuthType.LEGACY_CLOUD_SHELL,
118	      AuthType.COMPUTE_ADC,
119	    ]);
120	    if (authType && blockedAuthTypes.has(authType)) {
121	      return 'Visual agent model not available for current auth type.';
122	    }
123	    return undefined;
124	  }
125	
126	  const allTools: AnyDeclarativeTool[] = [...mcpTools];
127	  const visionDisabledReason = getVisionDisabledReason();
128	
129	  if (visionDisabledReason) {
130	    debugLogger.log(`Vision disabled: ${visionDisabledReason}`);
131	  } else {
132	    allTools.push(
133	      createAnalyzeScreenshotTool(browserManager, config, messageBus),
134	    );
135	  }
136	
137	  debugLogger.log(
138	    `Created ${allTools.length} tools for browser agent: ` +
139	      allTools.map((t) => t.name).join(', '),
140	  );
141	
142	  // Create configured definition with tools
143	  // BrowserAgentDefinition is a factory function - call it with config
144	  const baseDefinition = BrowserAgentDefinition(config, !visionDisabledReason);
145	  const definition: LocalAgentDefinition<typeof BrowserTaskResultSchema> = {
146	    ...baseDefinition,
147	    toolConfig: {
148	      tools: allTools,
149	    },
150	  };
151	
152	  return { definition, browserManager };
153	}
